            if (c == delimiter || c == '\\') out.append('\\').append(c);
            else out.append(switch (c) {
                case '\b' -> "\\b"; case '\f' -> "\\f"; case '\n' -> "\\n"; case '\r' -> "\\r"; case '\t' -> "\\t"; default -> c < 32 || c == 127 ? String.format(Locale.ROOT, "\\u%04x", (int)c) : "" + c;
            });
        return out.append(delimiter).toString();
